import mujoco, numpy as np, time
base=open('model_ref.xml').read()
C='<compiler autolimits="true"/>'
def make(sub,path):
    x=base
    for a,b in sub: x=x.replace(a,b)
    open(path,'w').write(x); return mujoco.MjModel.from_xml_path(path)
def sim(m,seed):
    d=mujoco.MjData(m); n=int(2.0/m.opt.timestep)
    rng=np.random.default_rng(seed); d.qpos+=rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    for _ in range(n): mujoco.mj_step(m,d)
    s=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(m,d,s,mujoco.mjtState.mjSTATE_FULLPHYSICS); return s
mref=mujoco.MjModel.from_xml_path('model_ref.xml')
V={
 'ts0.0025':[(C,C+'<option timestep="0.0025"/>')],
 'ts0.004':[(C,C+'<option timestep="0.004"/>')],
 'rk4_ts0.004':[(C,C+'<option timestep="0.004" integrator="RK4"/>')],
 'rk4_ts0.008':[(C,C+'<option timestep="0.008" integrator="RK4"/>')],
 'implicit_ts0.004':[(C,C+'<option timestep="0.004" integrator="implicit"/>')],
}
for k,v in V.items():
    try:
        m=make(v,'/tmp/s3_%s.xml'%k)
        ds=[np.abs(sim(m,s)-sim(mref,s)).max() for s in (1,7)]
        t=[];
        for r in range(3):
            t0=time.perf_counter(); sim(m,r); t.append(time.perf_counter()-t0)
        print(f'{k:20s} t={min(t):.4f} maxdiff={max(ds):.2e}')
    except Exception as e: print(k,'ERR',repr(e)[:100])
EOF
python3 /tmp/sweep3.py 2>&1 | grep -v WARNING

