import mujoco, numpy as np, time, itertools, sys
base=open('model_ref.xml').read(); C='<compiler autolimits="true"/>'
def mk(opt,p):
    open(p,'w').write(base.replace(C,C+opt)); return mujoco.MjModel.from_xml_path(p)
def sim(m,seed):
    d=mujoco.MjData(m); n=int(2.0/m.opt.timestep)
    rng=np.random.default_rng(seed); d.qpos+=rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    for _ in range(n): mujoco.mj_step(m,d)
    s=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(m,d,s,mujoco.mjtState.mjSTATE_FULLPHYSICS); return s
P='<option jacobian="dense" solver="PGS" tolerance="1e-14" iterations="200"'
V={
 'pgs':P+'/>',
 'pgs_nocon':P+'><flag contact="disable"/></option>',
 'pgs_nocon_act':P+'><flag contact="disable" actuation="disable"/></option>',
 'pgs_nocon_act_rs':P+'><flag contact="disable" actuation="disable" refsafe="disable" sensor="disable" clampctrl="disable"/></option>',
 'pgs_it20':'<option jacobian="dense" solver="PGS" tolerance="1e-14" iterations="20"><flag contact="disable" actuation="disable"/></option>',
}
mref=mujoco.MjModel.from_xml_path('model_ref.xml')
models={k:mk(v,'/tmp/b_%s.xml'%k) for k,v in V.items()}
refs={s:sim(mref,s) for s in range(8)}
for k,m in models.items():
    print(k,'maxdiff %.2e'%max(np.abs(sim(m,s)-refs[s]).max() for s in range(8)))
# interleaved timing
keys=list(models)+['REF']
models['REF']=mref
T={k:[] for k in keys}
for r in range(12):
    for k in keys:
        t0=time.perf_counter(); sim(models[k],r); T[k].append(time.perf_counter()-t0)
tr=np.array(T['REF'])
for k in keys:
    a=np.array(T[k])
    print(f'{k:20s} min={a.min():.4f} med={np.median(a):.4f} pct_min={a.min()/tr.min():.3f} pct_meanratio={(a/tr).mean():.3f}')
EOF
